const express = require('express');
const router = express.Router();
const OpenAI = require('openai');

const openai = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY
});

// POST /api/generate-itinerary (keeping for backward compatibility)
router.post('/generate-itinerary', async (req, res) => {
  const { tripType, vibe, budget, duration } = req.body;

  const prompt = `
You are WanderGenie, a travel planning AI assistant. Based on the user's preferences:
- Trip Type: ${tripType}
- Vibe: ${vibe}
- Budget: ${budget}
- Duration: ${duration}

Generate:
1. Destination recommendation
2. Day-wise itinerary
3. Local travel tips
4. Estimated budget summary

Format the response as a JSON object with the following structure:
{
  "destination": "Recommended destination name",
  "duration": "${duration}",
  "budget": "${budget}",
  "itinerary": [
    {
      "day": 1,
      "activities": ["Activity 1", "Activity 2", "Activity 3"]
    },
    {
      "day": 2,
      "activities": ["Activity 1", "Activity 2", "Activity 3"]
    }
  ],
  "tips": ["Tip 1", "Tip 2", "Tip 3"],
  "estimatedCosts": {
    "accommodation": "$X",
    "food": "$X",
    "activities": "$X", 
    "transportation": "$X",
    "total": "$X"
  }
}
`;

  try {
    const response = await openai.chat.completions.create({
      messages: [{ role: "user", content: prompt }],
      model: "gpt-4",
      response_format: { type: "json_object" }
    });

    // Parse the response to ensure it's valid JSON
    const content = response.choices[0].message.content;
    const tripPlan = JSON.parse(content);

    res.json({ 
      tripPlan,
      userSelections: {
        tripType,
        vibe,
        budget,
        duration
      }
    });
  } catch (error) {
    console.error("AI generation failed:", error);
    res.status(500).json({ 
      error: "AI generation failed", 
      details: error.message 
    });
  }
});

// POST /api/ai/plan - New endpoint with enhanced error handling
router.post('/ai/plan', async (req, res) => {
  console.log('Received trip planning request:', req.body);
  
  const { tripType, vibe, budget, duration } = req.body;
  
  // Validate required parameters
  if (!tripType || !vibe || !budget || !duration) {
    console.error('Missing required parameters:', { tripType, vibe, budget, duration });
    return res.status(400).json({ 
      error: "Missing required parameters",
      missingFields: Object.entries({ tripType, vibe, budget, duration })
        .filter(([_, value]) => !value)
        .map(([key]) => key)
    });
  }

  const prompt = `
You are WanderGenie, a travel planning AI assistant. Based on the user's preferences:
- Trip Type: ${tripType}
- Vibe: ${vibe}
- Budget: ${budget}
- Duration: ${duration}

Generate:
1. Destination recommendation that matches these preferences
2. Detailed day-wise itinerary appropriate for the duration
3. Local travel tips specific to the destination
4. Realistic estimated budget summary

Format the response as a JSON object with the following structure:
{
  "destination": "Recommended destination name",
  "duration": "${duration}",
  "budget": "${budget}",
  "itinerary": [
    {
      "day": 1,
      "activities": ["Activity 1", "Activity 2", "Activity 3"]
    },
    {
      "day": 2,
      "activities": ["Activity 1", "Activity 2", "Activity 3"]
    }
  ],
  "tips": ["Tip 1", "Tip 2", "Tip 3"],
  "estimatedCosts": {
    "accommodation": "$X",
    "food": "$X",
    "activities": "$X", 
    "transportation": "$X",
    "total": "$X"
  }
}
`;

  try {
    console.log('Sending request to OpenAI...');
    console.time('openai_request');
    
    const response = await openai.chat.completions.create({
      messages: [{ role: "user", content: prompt }],
      model: "gpt-4",
      response_format: { type: "json_object" }
    });
    
    console.timeEnd('openai_request');
    console.log('Received response from OpenAI');

    // Parse the response to ensure it's valid JSON
    const content = response.choices[0].message.content;
    let tripPlan;
    
    try {
      tripPlan = JSON.parse(content);
    } catch (parseError) {
      console.error('Failed to parse OpenAI response as JSON:', content);
      return res.status(500).json({
        error: "Invalid response format from AI service",
        details: parseError.message
      });
    }

    console.log('Successfully generated trip plan for:', tripType, vibe, budget, duration);
    
    res.json({ 
      tripPlan,
      userSelections: {
        tripType,
        vibe,
        budget,
        duration
      }
    });
  } catch (error) {
    console.error("AI generation failed:", error);
    
    // More detailed error handling
    let statusCode = 500;
    let errorMessage = "AI generation failed";
    
    if (error.response) {
      statusCode = error.response.status || 500;
      errorMessage = `OpenAI API error: ${error.response.statusText || 'Unknown error'}`;
      console.error('OpenAI API response error:', error.response.data);
    } else if (error.code === 'ECONNREFUSED' || error.code === 'ENOTFOUND') {
      errorMessage = 'Cannot connect to AI service. Please check your network connection.';
    }
    
    res.status(statusCode).json({ 
      error: errorMessage, 
      details: error.message 
    });
  }
});

module.exports = router; 